'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),vm=require('node:vm'),fs=require('node:fs');
const source=fs.readFileSync('navigation-art.js','utf8');
function clock(){let now=0,id=0;const jobs=new Map();return {set(fn,ms){const key=++id;jobs.set(key,{at:now+ms,fn});return key;},clear(key){jobs.delete(key)},advance(ms){const end=now+ms;while(true){const next=[...jobs].filter(([,j])=>j.at<=end).sort((a,b)=>a[1].at-b[1].at)[0];if(!next)break;jobs.delete(next[0]);now=next[1].at;next[1].fn()}now=end},size:()=>jobs.size};}
function model(){const c={window:{}};vm.runInNewContext(source,c);return c.window.PhoenixNavigationArt;}
function sequence(reduced=false){const time=clock(),playing=new Set(),calls=[];let active=-1;const engines=Array.from({length:5},(_,i)=>({play(){playing.add(i);calls.push(i);assert.equal(playing.size,1)},stop(){playing.delete(i)}}));const api=model().createSequence(engines,{setTimer:time.set,clearTimer:time.clear,reduced:()=>reduced,onPlaying:i=>active=i});return {api,time,playing,calls,active:()=>active};}
test('five destinations and one warnings action reference real assets without altering game state',()=>{const a=model();assert.deepEqual(Array.from(a.entries,e=>e.key),['home','regions','reference','progress','constellation','warnings']);for(const entry of a.entries){assert.ok(fs.statSync(entry.src).size>1000);if(entry.key!=='warnings')assert.ok(entry.href.startsWith('#'));}assert.equal(new Set(a.entries.filter(e=>e.href).map(e=>e.href)).size,5);});
test('nested guide routes select their owning category',()=>{const a=model();for(const [route,key]of [['#home','home'],['#quest-lilac/4','regions'],['#departure-check','regions'],['#whiteorchard-tree/hub-hunt/q-beast','regions'],['#whiteorchard-constellation/whiteorchard','constellation'],['#gear-diagrams','reference'],['#economy-merchants','reference'],['#character-gear','reference'],['#progress','progress']])assert.equal(a.keyForRoute(route),key);});
test('arrival plays every category once and never overlaps effects',()=>{const x=sequence();x.api.open();assert.deepEqual(x.calls,[0]);for(let i=1;i<5;i++){x.time.advance(8150);assert.equal(x.active(),i)}x.time.advance(8150);assert.deepEqual(x.calls,[0,1,2,3,4]);assert.equal(x.playing.size,0);assert.equal(x.time.size(),0);});
test('individual touch interrupts arrival and only restarts the touched category',()=>{const x=sequence();x.api.open();x.time.advance(500);x.api.touch(3);assert.deepEqual(x.calls,[0,3]);assert.deepEqual([...x.playing],[3]);x.time.advance(50000);assert.deepEqual(x.calls,[0,3]);assert.equal(x.playing.size,0);x.api.touch(4);assert.deepEqual([...x.playing],[4]);});
test('closing cancels rendering and returning does not restart an arrival sequence',()=>{const x=sequence();x.api.open();x.api.close();x.time.advance(50000);assert.equal(x.playing.size,0);x.api.open();x.time.advance(50000);assert.deepEqual(x.calls,[0]);x.api.touch(2);assert.deepEqual([...x.playing],[2]);});
test('reduced motion retains all destinations while suppressing animated rendering',()=>{const x=sequence(true);x.api.open();x.api.touch(4);x.time.advance(50000);assert.deepEqual(x.calls,[]);assert.equal(x.playing.size,0);assert.equal(x.time.size(),0);});
test('quieting an open menu cancels pending arrival and still allows deliberate replay',()=>{const x=sequence();x.api.open();x.time.advance(9000);x.api.quiet();x.time.advance(50000);assert.deepEqual(x.calls,[0,1]);x.api.touch(1);assert.deepEqual(x.calls,[0,1,1]);});
class Node{
 constructor(tag,doc){this.tagName=tag.toUpperCase();this.doc=doc;this.children=[];this.attrs={};this.dataset={};this.style={setProperty(){}};this.className='';this.hidden=false;this.inert=false;this.listeners={};this.scrollTop=0;this.isConnected=true;this.classList={add:(...xs)=>this.className=[...new Set(this.className.split(' ').filter(Boolean).concat(xs))].join(' '),remove:(...xs)=>this.className=this.className.split(' ').filter(x=>!xs.includes(x)).join(' '),contains:x=>this.className.split(' ').includes(x),toggle:(x,on)=>{if(on===undefined)on=!this.classList.contains(x);on?this.classList.add(x):this.classList.remove(x);}};if(tag==='img')this.decode=()=>Promise.resolve();}
 prepend(...nodes){this.children.unshift(...nodes)}
 append(...nodes){this.children.push(...nodes)}replaceChildren(...nodes){this.children=nodes}setAttribute(k,v){this.attrs[k]=String(v)}getAttribute(k){return this.attrs[k]??null}removeAttribute(k){delete this.attrs[k]}
 addEventListener(k,fn){(this.listeners[k]??=[]).push(fn)}removeEventListener(k,fn){this.listeners[k]=(this.listeners[k]||[]).filter(x=>x!==fn)}
 matches(s){if(s[0]==='.')return this.classList.contains(s.slice(1));if(s.startsWith('[data-'))return Object.hasOwn(this.dataset,s.slice(6,-1).replace(/-([a-z])/g,(_,x)=>x.toUpperCase()));return s===this.tagName.toLowerCase()}
 querySelector(s){for(const child of this.children){if(child.matches(s))return child;const found=child.querySelector(s);if(found)return found;}return null}
 querySelectorAll(s){return this.children.flatMap(n=>[...(n.matches(s)?[n]:[]),...n.querySelectorAll(s)]);}
 focus(){this.doc.activeElement=this}
}
function decorate(){let acknowledgements=0;const time=clock(),document={hidden:false,listeners:{},addEventListener:Node.prototype.addEventListener,removeEventListener:Node.prototype.removeEventListener};document.createElement=tag=>new Node(tag,document);document.body=new Node('body',document);const main=new Node('main',document),header=new Node('header',document),prior=new Node('button',document);document.activeElement=prior;document.querySelector=s=>s==='main'?main:header;const events={},warningData={items:[{id:'poi-4',name:'Crystal skull',status:'Unknown',cutoff:'Before the hunt hand-in',verify:'Check inventory',final:true,art:'art-white-orchard-illustrated/poi-4.webp'}],count:1,final:true},viewport={scrollY:444,lock(){this.locked=true},unlock(){this.locked=false},scrollTo(x,y){this.scrollY=y}};const media={matches:false,addEventListener(){},removeEventListener(){}};const effects=[];const window={PhoenixWarningCenter:{get:()=>warningData},setTimeout:time.set,clearTimeout:time.clear,PhoenixViewport:viewport,matchMedia:()=>media,addEventListener:(k,fn)=>events[k]=fn,removeEventListener:k=>delete events[k],PhoenixNavigationEffects:{create(root,key){const effect={key,playing:false,play(){this.playing=true},stop(){this.playing=false},destroy(){this.stop()}};effects.push(effect);return effect}}};const location={hash:'#quest-lilac/4'};vm.runInNewContext(source,{window,document,location,Promise});const fan=new Node('nav',document),root=new Node('aside',document),historyToggle=new Node('button',document);historyToggle.hidden=true;const callbacks=[];for(let i=0;i<5;i++){const button=new Node('button',document),fn=()=>callbacks.push(i);button.onclick=fn;fan.append(button)}const wolf=new Node('button',document);wolf.className='medallion-core';wolf.setAttribute('aria-label','Read guide warning');root.append(fan,wolf);const cards=[...fan.children],originalHandlers=cards.map(c=>c.onclick);const api=window.PhoenixNavigationArt.decorate({root,fan,open(){api.open()},close(){api.close()},showHistory(){callbacks.push('history')},acknowledgeWarnings(){acknowledgements++;},historyToggle});return {get acknowledgements(){return acknowledgements;},api,fan,root,wolf,warningData,warnings:fan.querySelector('.art-navigation-row').children.at(-1).querySelector('button'),cards,originalHandlers,document,viewport,main,header,prior,historyToggle,callbacks,time,effects,location,events,window};}
test('actual menu renderer keeps five existing navigation callbacks and hides unavailable utilities',()=>{const x=decorate();assert.equal(x.cards.length,5);x.cards.forEach((card,i)=>{assert.equal(card.onclick,x.originalHandlers[i]);assert.equal(card.hidden,false);assert.ok(card.querySelector('canvas'));assert.ok(card.querySelector('img'));});x.api.open();assert.equal(x.fan.querySelector('.art-warning-count').textContent,'1');assert.equal(x.fan.querySelector('.art-warning-final').hidden,false);assert.equal(x.cards[1].getAttribute('aria-current'),'page');});
test('actual menu open/close preserves reader position, focus, and inert state',async()=>{const x=decorate();x.api.open();await Promise.resolve();await Promise.resolve();assert.equal(x.viewport.locked,true);assert.equal(x.main.inert,true);assert.equal(x.header.inert,true);assert.equal(x.document.activeElement,x.cards[1]);x.api.close();assert.equal(x.viewport.scrollY,444);assert.equal(x.viewport.locked,false);assert.equal(x.main.inert,false);assert.equal(x.header.inert,false);assert.equal(x.document.activeElement,x.prior);assert.ok(x.effects.every(e=>!e.playing));});
test('route correction changes selection; sixth tile opens a takeover and Return restores the source',()=>{const x=decorate();x.api.open();x.location.hash='#progress';x.events['phoenix:route-rendered']();assert.equal(x.cards[3].getAttribute('aria-current'),'page');assert.equal(x.cards[1].getAttribute('aria-current'),null);x.warnings.onclick();assert.equal(x.fan.querySelector('.art-navigation-row').hidden,true);assert.equal(x.fan.querySelector('.art-warning-list').hidden,false);assert.equal(x.fan.querySelector('.art-warning-final-inline').textContent,'FINAL');assert.deepEqual(x.callbacks,[]);x.fan.querySelector('.art-warning-back').onclick();assert.equal(x.viewport.locked,false);assert.equal(x.fan.classList.contains('warnings-takeover'),false);});
test('two-column keyboard navigation follows rows and reaches the sixth tile without activating routes',()=>{const x=decorate();x.api.open();const press=key=>x.root.listeners.keydown[0]({key,preventDefault(){}});assert.equal(x.document.activeElement,x.cards[1]);press('ArrowDown');assert.equal(x.document.activeElement,x.cards[3]);press('ArrowDown');assert.equal(x.document.activeElement,x.warnings);press('ArrowUp');assert.equal(x.document.activeElement,x.cards[3]);press('ArrowLeft');assert.equal(x.document.activeElement,x.cards[2]);assert.deepEqual(x.callbacks,[]);});
test('assets and scripts load before console construction',()=>{const html=fs.readFileSync('index.html','utf8');assert.ok(html.indexOf('navigation-effects.js')<html.indexOf('main-console.js'));assert.ok(html.indexOf('navigation-art.js')<html.indexOf('main-console.js'));assert.ok(html.includes('navigation-art.css'));});

test('popup keeps the wolf inside modal focus order and uses it to close without navigating',()=>{const x=decorate();x.api.open();assert.equal(x.root.getAttribute('role'),'dialog');assert.equal(x.wolf.getAttribute('aria-label'),'Close guide navigation');x.cards[4].focus();let prevented=false;x.root.listeners.keydown[0]({key:'Tab',preventDefault(){prevented=true}});assert.equal(prevented,false);x.wolf.focus();x.root.listeners.keydown[0]({key:'Tab',preventDefault(){prevented=true}});assert.equal(x.document.activeElement,x.fan.querySelector('.art-search-trigger'));x.wolf.listeners.click[0]({preventDefault(){},stopImmediatePropagation(){}});assert.equal(x.viewport.locked,false);assert.equal(x.root.getAttribute('aria-modal'),null);assert.equal(x.wolf.getAttribute('aria-label'),'Read guide warning');assert.deepEqual(x.callbacks,[]);});

test('warning count refresh and empty list never claim all game content is safe',()=>{const x=decorate();x.api.open();x.warningData.items=[];x.warningData.count=0;x.warningData.final=false;x.events['phoenix:progress-committed']();assert.equal(x.fan.querySelector('.art-warning-count').textContent,'0');assert.equal(x.fan.querySelector('.art-warning-final').hidden,false);assert.equal(x.warnings.classList.contains('has-final-risk'),false);x.warnings.onclick();assert.equal(x.fan.querySelector('.art-warning-empty').textContent,'No unresolved warnings recorded.');assert.deepEqual(x.callbacks,[])});
test('returning from shared details reopens the warning list at its saved scroll without a route change',()=>{const x=decorate();x.api.open();x.api.close();x.events['phoenix:warning-menu-return']({detail:{listY:77,warningId:'poi-4'}});assert.equal(x.fan.querySelector('.art-warning-list').hidden,false);assert.equal(x.fan.querySelector('.art-warning-list').scrollTop,77);assert.equal(x.viewport.locked,true);assert.deepEqual(x.callbacks,[])});


test('opening directly into the reading list consumes arrival quietly and permits later deliberate effects',()=>{const x=sequence();x.api.open({quiet:true});assert.deepEqual(x.calls,[]);x.api.open();assert.deepEqual(x.calls,[]);x.api.touch(2);assert.deepEqual(x.calls,[2]);});

test('FINAL stays engraved on the artwork and only lights for an immediate risk',()=>{const x=decorate();x.api.open();const label=x.fan.querySelector('.art-warning-final');assert.equal(x.warnings.querySelector('.art-navigation-picture').children.includes(label),true);assert.equal(x.warnings.classList.contains('has-final-risk'),true);x.warningData.final=false;x.warningData.items[0].final=false;x.events['phoenix:route-rendered']();assert.equal(label.hidden,false);assert.equal(label.getAttribute('aria-hidden'),'true');assert.equal(x.warnings.classList.contains('has-final-risk'),false);});
test('warning list shows final and unresolved counts with a shared-entry illustration',()=>{const x=decorate();x.api.open();x.warnings.onclick();assert.equal(x.fan.querySelector('.art-warning-summary').textContent,'1 open risks · 0 unknown · 1 final');assert.equal(x.fan.querySelector('.art-warning-illustration').src,'art-white-orchard-illustrated/poi-4.webp');assert.deepEqual(x.callbacks,[]);});

test('Search bar opens above the art grid and returns through its existing menu callback',()=>{const x=decorate();let calls=0,options;x.window.PhoenixSearch={open(trigger,next){calls++;options=next;}};x.api.open();const button=x.fan.querySelector('.art-search-trigger'),panel=x.fan.querySelector('.art-navigation-panel');assert.ok(panel.children.indexOf(button)<panel.children.indexOf(x.fan.querySelector('.art-navigation-row')));assert.equal(button.getAttribute('aria-label'),'Open Search');button.onclick();assert.equal(calls,1);assert.equal(x.viewport.locked,false);options.reopen();assert.equal(x.viewport.locked,true);x.warnings.onclick();assert.equal(button.hidden,true);x.fan.querySelector('.art-warning-back').onclick();assert.equal(x.viewport.locked,false);});

test('Warnings is a takeover while navigation remains a popup; acknowledgement does not alter unresolved membership',()=>{const x=decorate();x.api.open();assert.equal(x.acknowledgements,0);assert.equal(x.fan.classList.contains('warnings-takeover'),false);x.warnings.onclick();assert.equal(x.acknowledgements,1);assert.equal(x.fan.classList.contains('warnings-takeover'),true);assert.equal(x.warningData.count,1);assert.equal(x.wolf.getAttribute('aria-label'),'Close Warnings');x.viewport.scrollY=9;x.fan.querySelector('.art-warning-back').onclick();assert.equal(x.viewport.scrollY,444);assert.equal(x.viewport.locked,false);});
test('wolf closes the Warnings takeover without navigation or progress mutation',()=>{const x=decorate();x.api.open();x.api.showWarnings();x.wolf.listeners.click[0]({preventDefault(){},stopImmediatePropagation(){}});assert.equal(x.viewport.locked,false);assert.equal(x.viewport.scrollY,444);assert.equal(x.warningData.count,1);assert.deepEqual(x.callbacks,[]);});
